func refuseOwnedPageIfConfigured(ctx context.Context, params ActionParams, res interface{}, siteID uuid.UUID, logger *zap.Logger) (interface{}, error) {
	refuse, _ := params.StepConfig.Config["refuse_owned_page"].(bool)
	if !refuse { return res, nil }
	m, ok := res.(map[string]interface{})
	if !ok { return res, nil }
	if found, _ := m["found"].(bool); !found { return res, nil }
	pageID, err := uuid.Parse(m["id"].(string)) // stand down if unparsable
	...
	owned, checked := pageIsOwnedForGuard(ctx, params.DB, pageID, logger)
	if !checked { /* Warn + stand down — save-path guard remains */ return res, nil }
	if !owned { return res, nil }
	reason := fmt.Sprintf("%s: page %s is rebuild_policy=owned (tool/widget-owned); refused at load, before the content writer runs — ...", ownedPageSkipReasonPrefix, pageName)
	emitOwnedPageReviewItem(ctx, params.DB, siteID, pageName, "load_page_record", reason, logger)
	return nil, fmt.Errorf("%s", reason)
}
